  "diagram": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 290 180\" width=\"290\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" font-family=\"sans-serif\" font-size=\"13\"><line x1=\"80.0\" y1=\"30.0\" x2=\"180.0\" y2=\"30.0\" /><line x1=\"40.0\" y1=\"150.0\" x2=\"240.0\" y2=\"150.0\" /><line x1=\"80.0\" y1=\"30.0\" x2=\"240.0\" y2=\"150.0\" /><line x1=\"180.0\" y1=\"30.0\" x2=\"40.0\" y2=\"150.0\" /><polyline points=\"123.8,33.3 130.0,30.0 123.8,26.7\" /><polyline points=\"143.8,153.3 150.0,150.0 143.8,146.7\" /><text x=\"72.0\" y=\"26.0\" text-anchor=\"middle\" fill=\"currentColor\" stroke=\"none\" >V</text><text x=\"188.0\" y=\"26.0\" text-anchor=\"middle\" fill=\"currentColor\" stroke=\"none\" >W</text><text x=\"32.0\" y=\"164.0\" text-anchor=\"middle\" fill=\"currentColor\" stroke=\"none\" >Z</text><text x=\"248.0\" y=\"164.0\" text-anchor=\"middle\" fill=\"currentColor\" stroke=\"none\" >Y</text><text x=\"123.3\" y=\"74.0\" text-anchor=\"middle\" fill=\"currentColor\" stroke=\"none\" >X</text><text x=\"176.0\" y=\"58.0\" text-anchor=\"end\" fill=\"currentColor\" stroke=\"none\" >6 cm</text><text x=\"75.0\" y=\"112.0\" text-anchor=\"end\" fill=\"currentColor\" stroke=\"none\" >12 cm</text><text x=\"200.0\" y=\"100.0\" text-anchor=\"start\" fill=\"currentColor\" stroke=\"none\" >16 cm</text><text x=\"140.0\" y=\"168.0\" text-anchor=\"middle\" fill=\"currentColor\" stroke=\"none\" >20 cm</text></svg>",
